<script setup lang="ts">
import { onBeforeUnmount, ref, watch } from 'vue';import { useRouter } from 'vue-router';import * as api from '@/api/tracking';import type {DevelopmentState,Point} from '@/api/tracking';import CodeExamples from '@/components/points/CodeExamples.vue';import { developmentStateOptions } from '@/constants/enum-options'
const props=defineProps<{projectId:number;pointId:number;canMutate:boolean}>();const router=useRouter(),point=ref<Point>(),loading=ref(false),error=ref(''),copyOpen=ref(false),copyCode=ref(''),deprecateOpen=ref(false),reason=ref(''),replacementId=ref<number>(),publishedPoints=ref<Point[]>([]);let controller:AbortController|undefined
async function load(){controller?.abort();const active=new AbortController();controller=active;loading.value=true;error.value='';point.value=undefined;try{point.value=await api.getPoint(props.projectId,props.pointId,active.signal)}catch(e){if((e as{name?:string}).name!=='CanceledError')error.value=e instanceof Error?e.message:'点位加载失败'}finally{if(controller===active)loading.value=false}}
watch(()=>[props.projectId,props.pointId],()=>{copyOpen.value=false;deprecateOpen.value=false;void load()},{immediate:true});onBeforeUnmount(()=>controller?.abort())
async function copy(){if(!point.value||!copyCode.value)return;try{const p=await api.copyPoint(props.projectId,point.value.id,copyCode.value);await router.push({name:'point-detail',params:{projectId:props.projectId,pointId:p.id}})}catch(e){error.value=e instanceof Error?e.message:'复制失败'}}
async function openDeprecate(){const result=await api.listPoints(props.projectId,{definition_state:'PUBLISHED',page_size:100});publishedPoints.value=result.items.filter(p=>p.id!==props.pointId);deprecateOpen.value=true}
async function deprecate(){if(!point.value||!reason.value.trim())return;try{await api.deprecatePoint(props.projectId,point.value.id,reason.value,replacementId.value);deprecateOpen.value=false;await load()}catch(e){error.value=e instanceof Error?e.message:'废弃失败'}}
async function setDevelopmentState(v:string){if(!point.value)return;try{point.value=await api.updateDevelopmentState(props.projectId,point.value.id,v as DevelopmentState)}catch(e){error.value=e instanceof Error?e.message:'开发状态更新失败'}}
</script>
<template><section><header class="page-heading"><div><button class="back-link" @click="router.push({name:'points',params:{projectId}})">← 返回点位列表</button><h1>{{ point?.name || '点位详情' }}</h1><p v-if="point"><code>{{ point.code }}</code> · v{{ point.published_version || 0 }}</p></div><div v-if="point&&canMutate" class="heading-actions"><button v-if="point.definition_state==='DRAFT'" data-test="edit-point" class="primary-button" @click="router.push({name:'points',params:{projectId},query:{edit:point.id}})">编辑草稿</button><button v-if="point.definition_state==='PUBLISHED'" data-test="copy-point" class="secondary-button" @click="copyOpen=true;copyCode=point.code+'_copy'">复制新增</button><button v-if="point.definition_state==='PUBLISHED'" class="danger-button" @click="openDeprecate">废弃点位</button></div></header><div v-if="loading" class="empty-state">正在加载点位…</div><div v-else-if="error" class="form-alert" role="alert">{{ error }} <button @click="load">重试</button></div><div v-else-if="point" class="detail-grid"><article class="detail-card"><h2>定义</h2><dl><div><dt>分类路径</dt><dd>{{ point.category_path.map(c=>c.name).join(' / ') || point.category.name }}</dd></div><div><dt>行为类型</dt><dd>{{ point.behavior_type }}</dd></div><div><dt>定义状态</dt><dd><span class="state-chip">{{ point.definition_state }}</span></dd></div><div><dt>开发状态</dt><dd><select v-if="canMutate&&point.definition_state!=='DEPRECATED'" :value="point.development_state" @change="setDevelopmentState(($event.target as HTMLSelectElement).value)"><option v-for="option in developmentStateOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select><span v-else>{{ point.development_state }}</span></dd></div><div><dt>说明</dt><dd>{{ point.description || '-' }}</dd></div></dl></article><article class="detail-card"><h2>触发与统计</h2><dl><div><dt>触发页面</dt><dd>{{ point.trigger_page || '-' }}</dd></div><div><dt>触发时机</dt><dd>{{ point.trigger_timing || '-' }}</dd></div><div><dt>次数规则</dt><dd>{{ point.trigger_count_rule || '-' }}</dd></div><div><dt>指标</dt><dd>{{ point.count_pv?'PV ':'' }}{{ point.count_uv?`UV（${point.uv_mode}）`:'' }}</dd></div><div><dt>时间口径</dt><dd>{{ point.time_basis }}</dd></div><div><dt>平台</dt><dd>{{ point.supported_platforms.join('、') }}</dd></div></dl></article><article class="detail-card detail-card--wide"><h2>属性 Schema</h2><div v-if="!point.properties.length" class="empty-state">没有自定义属性</div><table v-else><thead><tr><th>编码</th><th>名称</th><th>类型</th><th>必填</th><th>约束</th><th>说明</th></tr></thead><tbody><tr v-for="p in point.properties" :key="p.code"><td><code>{{ p.code }}</code></td><td>{{ p.name }}</td><td>{{ p.type }}</td><td>{{ p.required?'是':'否' }}</td><td>{{ p.enum_values?.join('、') || p.array_item_type || '-' }}</td><td>{{ p.description || '-' }}</td></tr></tbody></table></article><article class="detail-card"><h2>协作信息</h2><dl><div><dt>产品负责人</dt><dd>{{ point.product_owner || '-' }}</dd></div><div><dt>开发负责人</dt><dd>{{ point.developer_owner || '-' }}</dd></div><div><dt>需求文档</dt><dd><a v-if="point.requirement_url" :href="point.requirement_url" target="_blank" rel="noreferrer">打开链接</a><span v-else>-</span></dd></div><div v-if="point.deprecation_reason"><dt>废弃原因</dt><dd>{{ point.deprecation_reason }}</dd></div></dl></article><article class="detail-card"><h2>上报示例</h2><CodeExamples :project-id="projectId" :point-code="point.code" :platform="point.supported_platforms[0] || 'web'" :properties="point.properties" /></article></div><div v-if="copyOpen" class="modal-backdrop"><form class="modal-card wizard-form" role="dialog" aria-modal="true" aria-label="复制点位" @submit.prevent="copy"><h2>复制为新草稿</h2><label>新点位编码<input v-model="copyCode" pattern="[a-z][a-z0-9_]{2,127}" required></label><footer class="wizard-actions"><button type="button" class="secondary-button" @click="copyOpen=false">取消</button><button class="primary-button">复制</button></footer></form></div><div v-if="deprecateOpen" class="modal-backdrop"><form class="modal-card wizard-form" role="alertdialog" aria-modal="true" aria-label="废弃点位确认" @submit.prevent="deprecate"><h2>确认废弃点位</h2><p>废弃后不会删除历史定义，且不能恢复。</p><label>废弃原因<textarea v-model="reason" required /></label><label>替代点位（可选）<select v-model.number="replacementId"><option :value="undefined">无</option><option v-for="p in publishedPoints" :key="p.id" :value="p.id">{{ p.name }}（{{ p.code }}）</option></select></label><footer class="wizard-actions"><button type="button" class="secondary-button" @click="deprecateOpen=false">取消</button><button class="danger-button">确认废弃</button></footer></form></div></section></template>
